import {ToolRegistry} from './src/orchestration/tools/registry.js';

// 1. register-time throw naming the tool
const r1 = new ToolRegistry();
try {
  r1.register({name: 'broken_weather', description: 'x', inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}}}, async () => 'unreachable');
  console.log('FAIL: no throw');
} catch (e) {
  console.log('register threw, names tool:', (e as Error).message.includes('broken_weather'), '|', (e as Error).message);
}

// 2. wrong-typed field: names path + expected type, no value in result
const r2 = new ToolRegistry();
let calls = 0;
r2.register({name: 'ssn_lookup', description: 'x', inputSchema: {type: 'object', properties: {ssn: {type: 'string'}}, required: ['ssn']}}, async () => { calls += 1; return 'found'; });
const rej = await r2.execute('ssn_lookup', {ssn: 123456789});
console.log('wrong type:', JSON.stringify(rej), 'calls:', calls);

// 3. function source: per-call schema honoured
let schemaB = false;
const r3 = new ToolRegistry();
r3.register(() => ({name: 'flex', description: 'x', inputSchema: schemaB ? {type: 'object', properties: {b: {type: 'number'}}, required: ['b']} : {type: 'object'}}), async () => 'ok');
const before = await r3.execute('flex', {a: 1});
schemaB = true;
const after = await r3.execute('flex', {a: 1});
console.log('function source stale-check:', before.result === 'ok', after.result !== 'ok' ? 'rejects against current schema' : 'FAIL stale');

// 4. pass-through of extra properties, no coercion
const r4 = new ToolRegistry();
let seen: unknown;
r4.register({name: 't', description: 'x', inputSchema: {type: 'object', properties: {s: {type: 'string'}}, required: ['s']}}, async input => { seen = input; return 'ok'; });
await r4.execute('t', {s: 'x', extra: 7});
console.log('pass-through:', JSON.stringify(seen));

// 5. unknown tool unchanged
try { await new ToolRegistry().execute('nope', {}); } catch (e) { console.log('unknown tool:', (e as Error).message); }
EOF
